.card {
 text-align: center;
 padding: 20px 5px 8px 5px;
 background-color: #000;
 font-family: Segoe UI, sans-serif, M Plus 2;
}

.mobile .card {
 text-align: center;
 color: black;
 padding: 13px 5px 5px 5px;
}

/***************default anki audio button styling to be overridden--------
.replay-button { text-decoration: none; display: inline-flex; vertical-align: middle; margin: 3px; }
.replay-button svg { width: 40px; height: 40px; }
.replay-button svg circle { fill: #fff; stroke: #414141; }
.replay-button svg path { fill: #414141; }
****************/

a {
 color: #fff;
}

.replay-button svg {
 display: none;
}

.replay-button {
 background-image: url(_play.png);
 background-size: 20px;
 display: inline-block;
 width: 30px;
 height: 25px;
 margin-left: -5px;
 background-repeat: no-repeat;
}

/**** ankidroid replay button restyle ****/

.replaybutton span svg {
 display: none;
}

.replaybutton span {
 display: none;
}

.replaybutton {
 background-image: url(_play.png);
 background-size: 20px;
 display: inline-block;
 width: 30px;
 height: 19px;
 margin-left: 10px;
 background-repeat: no-repeat;
}

.container {
 max-width: 800px;
 margin: 0 auto;
 margin-top: 5%;
}

.mobile .container {
 margin-top: 0px;
}

.gp {
 font-size: 35px;
 padding-top: 10px;
 padding-bottom: 15px;
}

.mobile .gp {
 font-size: 25px;
 padding-top: 8px;
 padding-bottom: 1px;
}

.frontbg {
 background-color: #18AD95;
 border-radius: 10px 10px 0px 0px;
 color: #fff;
 position: relative;
 left: 0;
}

.backbg {
 position: relative;
 top: -3px;
 background-color: #f9f9f9;
 padding: 15px 30px 15px 30px;
 border-radius: 0px 0px 10px 10px;
 color: #016ea6;
 text-align: left;
}

.mobile .backbg {
 top: -5px;
 padding: 10px 15px 10px 15px;
 border-radius: 0px 0px 10px 10px;
 font-size: 20px;
}

.explanationbg {
 font-style: italic;
 padding: 0 50px 23px 50px;
 margin-left: -5px;
 margin-top: -15px;
 color: #fff;
 font-size: 20px; 
 text-align: left;
}

.mobile .explanationbg {
 padding: 15px 40px 27px 40px;
 margin-top: -20px;
 color: #fff;
 font-size: 15px;
}

.jp {
 font-size: 24px;
 margin: 15px 25px 25px 25px;
}

.mobile .jp {
 font-size: 19px;
 margin: 8px 20px 15px 20px;
}

.eng {
 font-size: 20px;
 margin: 0 25px 10px 25px;
 font-family: "M Plus 2";
}

.mobile .eng {
 font-size: 15px;
 margin: -10px 20px 10px 20px;
 line-height: 125%;
}

.bookInfo {
color: #fff;
margin-top: 7px;
margin-left: 7px;
text-align: left;
}


.mobile .bookInfo {
color: #fff;
margin-top: 3px;
margin-left: 2px;
text-align: left;
font-size: 11px;
}

@font-face {
  font-family: "M Plus 2";
  src: url("_Mplus2-Regular.ttf");
}

 /**Allows for furigana to be hidden accept on hover (or touch for android)**/
ruby rt { visibility: hidden; } ruby:hover rt { visibility: visible; }

/******* NIGHT MODE STYLING *******/

.night_mode .backbg {
 background-color: #1F4369;
 color: #e6e6e6;
}

.night_mode .frontbg {
  background-color: #103154;
  color: #e6e6e6;
}

.night_mode .explanationbg {
 color: #e6e6e6;
}

.nightMode.card {
 background-color: #000;
}
